const navItems = [
  ['dashboard', 'Dashboard', 'grid'], ['patients', 'Patients', 'users'], ['create', 'New patient', 'userPlus'],
  ['schedule', 'Schedule', 'calendar'], ['notifications', 'Notifications', 'bell'],
];
