let state = { screen: 'dashboard', detailTab: 'Overview', patientDetailTab: 'Tổng quan', query: '', notifications: false, timelineFilter: 'All events' };
const app = document.querySelector('#app');
const toast = document.querySelector('#toast');

function logo() { return `<span class="mark-icon">${icon('pulse', 19)}</span><span>Pituitary Care</span>`; }
function initialsFor(name) { return name.split(' ').map(n => n[0]).join('').slice(0,2); }
function button(label, type = 'primary-button', name = '') { return `<button class="${type}" ${name ? `data-action="${name}"` : ''}>${label}</button>`; }

function shell(content, active = state.screen) {
  return `<div class="app-shell">
    <aside class="sidebar">
      <div class="brand-mark">${logo()}</div>
      <div class="side-section">Workspace</div>
      ${navItems.map(([id, label, ico]) => `<button class="nav-item ${active === id ? 'active' : ''}" data-nav="${id}">${icon(ico)}<span>${label}</span>${id === 'notifications' ? '<b class="nav-badge">4</b>' : ''}</button>`).join('')}
      <div class="side-section">Manage</div>
      <button class="nav-item" data-action="settings">${icon('settings')}<span>Settings</span></button>
      <div class="sidebar-bottom"><div class="user-chip"><div class="avatar">MC</div><div><strong>Dr. Maya Chen</strong><span>Endocrinology</span></div><button class="icon-button" data-action="logout" aria-label="Log out">${icon('logout', 15)}</button></div></div>
    </aside>
    <main class="main-shell">
      <header class="topbar"><div class="topbar-left"><div class="breadcrumbs">Clinic / <strong>${active === 'patients' ? 'Patients' : active === 'create' ? 'New patient' : active === 'notifications' ? 'Notifications' : active === 'schedule' ? 'Schedule' : 'Dashboard'}</strong></div></div><div class="topbar-actions"><div class="date-chip">${icon('calendar', 14)} Wednesday, 14 Aug 2026</div><button class="icon-button" data-action="notifications" aria-label="Open notifications">${icon('bell')}<i class="notif-dot"></i></button><div class="avatar">MC</div></div></header>
      <div class="page-content">${content}</div>
    </main>
  </div>${state.notifications ? notificationPanel() : ''}`;
}

function renderLogin() {
  app.innerHTML = `<div class="login-screen"><section class="login-brand"><div class="brand-mark">${logo()}</div><div class="login-copy"><div class="eyebrow">Clinical workspace · v1.0</div><h1>See the whole<br><span style="color:#68d5d0">patient story.</span></h1><p>A calm, focused workspace for pituitary teams to track what changed, what matters now, and what comes next.</p><div class="login-signature">Built for <span>Dr. Maya Chen</span> · Endocrinology</div></div></section><section class="login-panel"><form class="login-card" id="login-form"><div class="eyebrow">Welcome back</div><h2>Sign in to your clinic</h2><p>Continue to your clinical workspace.</p><div class="form-field"><label for="email">Work email</label><input class="input" id="email" type="email" value="maya.chen@northstarclinic.com" placeholder="name@clinic.com" required></div><div class="form-field"><label for="password">Password</label><div class="password-wrap"><input class="input" id="password" type="password" value="pituitary" placeholder="Enter your password" required><button type="button" data-action="password">${icon('eye', 16)}</button></div></div><div class="login-options"><label class="check"><input type="checkbox" checked> Keep me signed in</label><button type="button" class="text-button" data-action="forgot">Forgot password?</button></div><button type="submit" class="primary-button full" data-action="login">Sign in ${icon('arrow', 15)}</button><p class="login-note">Protected workspace · Your data is encrypted and access controlled.</p></form></section></div>`;
  const loginForm = document.querySelector('#login-form');
  loginForm?.addEventListener('submit', (event) => {
    event.preventDefault();
    state.screen = 'dashboard';
    state.notifications = false;
rerender();

    showToast('Welcome back, Dr. Chen');
  });
}

