function render() { if (state.screen === 'login') return renderLogin(); if (state.screen === 'dashboard') return renderDashboard(); if (state.screen === 'patients') return renderPatients(); if (state.screen === 'create') return renderCreate(); if (state.screen === 'detail') return renderDetail(); if (state.screen === 'notifications') { state.notifications = false; return shell(`<div class="page-heading"><div><div class="eyebrow">Stay informed</div><h1>Notifications</h1><p>Review alerts, reminders and investigation updates.</p></div><button class="secondary-button" data-action="mark-read">${icon('check',14)} Mark all as read</button></div><section class="card notification-page-list"><div class="notification-item unread"><div class="notification-icon red">${icon('alert',14)}</div><div><p><strong>Clinical alert:</strong> Emma Richardson reported visual deterioration.</p><span>10 minutes ago · Requires review</span></div><button class="secondary-button" data-nav="detail">Review patient</button></div><div class="notification-item unread"><div class="notification-icon gold">${icon('calendar',14)}</div><div><p><strong>Follow-up due:</strong> 8 patients are due this week.</p><span>1 hour ago · Care coordination</span></div><button class="secondary-button" data-nav="schedule">View schedule</button></div><div class="notification-item"><div class="notification-icon green">${icon('check',14)}</div><div><p>MRI report uploaded for Noah Williams.</p><span>Yesterday · Documents</span></div></div><div class="notification-item"><div class="notification-icon gold">${icon('clock',14)}</div><div><p>Investigation reminder: Sophia Martinez.</p><span>Yesterday · Hormone panel</span></div></div></section>`, 'notifications'); } if (state.screen === 'schedule') return shell(`<div class="page-heading"><div><div class="eyebrow">Care coordination</div><h1>Schedule</h1><p>Appointments and follow-up tasks for your clinic.</p></div><button class="primary-button" data-action="schedule-followup">${icon('plus',14)} Add appointment</button></div><div class="card"><div class="card-header"><div><h3>Wednesday, 14 August 2026</h3><p>4 appointments scheduled</p></div><div class="date-chip">${icon('calendar',14)} Week view</div></div><div class="schedule-list">${[['09:00','Emma Richardson','Follow-up','ER'],['10:30','Oliver James','New patient','OJ'],['11:15','Noah Williams','Follow-up','NW'],['14:00','Sophia Martinez','Follow-up','SM'],['15:30','Liam Thompson','Review','LT']].map(x => `<div class="schedule-row"><div class="schedule-time">${x[0]}</div><div class="schedule-person"><div class="mini-avatar">${x[3]}</div><div><strong>${x[1]}</strong><span>${x[2]} · Endocrinology</span></div></div><button class="secondary-button" data-nav="detail">Open record ${icon('arrow',12)}</button></div>`).join('')}</div></div>`, 'schedule'); return renderDashboard(); }

function showToast(message) { toast.textContent = message; toast.classList.add('show'); clearTimeout(window.toastTimer); window.toastTimer = setTimeout(() => toast.classList.remove('show'), 2600); }
function rerender() {
  const output = render();
  if (typeof output === 'string') app.innerHTML = output;
}

document.addEventListener('click', (event) => {
  const nav = event.target.closest('[data-nav]');
  const tab = event.target.closest('[data-tab]');
  const filter = event.target.closest('[data-filter]');
  const action = event.target.closest('[data-action]');
  if (nav) { const destination = nav.dataset.nav; state.screen = destination === 'detail' ? 'detail' : destination; state.notifications = false; rerender(); return; }
  if (tab) { state.screen = 'detail'; state.detailTab = tab.dataset.tab; state.notifications = false; rerender(); return; }
  if (filter) { state.timelineFilter = filter.dataset.filter; rerender(); return; }
  if (action) {
    const name = action.dataset.action;
    if (name === 'login') { state.screen = 'dashboard'; rerender(); showToast('Welcome back, Dr. Chen'); }
    else if (name === 'new-patient') { state.screen = 'create'; rerender(); }
    else if (name === 'notifications') { state.notifications = !state.notifications; rerender(); }
    else if (name === 'password') { const input = document.querySelector('#password'); if (input) input.type = input.type === 'password' ? 'text' : 'password'; }
    else if (name === 'forgot') showToast('Password reset instructions are on their way.');
    else if (name === 'logout') { state.screen = 'login'; state.notifications = false; rerender(); }
    else if (name === 'schedule-followup') showToast('Follow-up scheduled and tasks created.');
    else if (name === 'save') showToast('Changes saved to the patient record.');
    else if (name === 'message') showToast('Reminder queued for Emma Richardson.');
    else if (name === 'add-event') showToast('New event form opened.');
    else if (name === 'import') showToast('Import dialog ready.');
    else if (name === 'export' || name === 'print') showToast('Export prepared for download.');
    else if (['add-result','add-mri','add-med','upload','open-file','settings','mark-read'].includes(name)) showToast(name === 'mark-read' ? 'All notifications marked as read.' : 'This action is ready for your next entry.');
  }
});
document.addEventListener('input', (event) => { if (event.target.id === 'patient-search') { state.query = event.target.value; const table = document.querySelector('#patient-table'); if (table) table.innerHTML = patientRows(); } });
document.addEventListener('submit', (event) => { if (event.target.id === 'login-form') { event.preventDefault(); state.screen = 'dashboard'; rerender(); showToast('Welcome back, Dr. Chen'); } if (event.target.id === 'patient-form') { event.preventDefault(); state.screen = 'patients'; rerender(); showToast('Patient record created successfully.'); } });

