function render() {
  if (state.screen === 'login') return renderLogin();
  if (state.role === 'patient') return state.screen === 'patient-detail' ? patientDetailVn() : state.screen === 'patient-schedule' ? patientScheduleVn() : state.screen === 'patient-notifications' ? patientNotificationsVn() : patientDashboardVn();
  if (state.screen === 'patients') return renderPatientsVn();
  if (state.screen === 'create') return renderCreateVn();
  if (state.screen === 'edit-patient') return renderEditVn();
  if (state.screen === 'detail') return doctorDetailVn();
  if (state.screen === 'schedule') return doctorScheduleVn();
  if (state.screen === 'notifications') return doctorNotificationsVn();
  return doctorDashboardVn();
}
